command:
$ErrorActionPreference = "Stop"
git fetch origin main work/high-contrast-acceptance --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "92c16faf6c56c89cf4bff5230482db3ac312a82f") { throw "main moved" }
if ((git rev-parse origin/work/high-contrast-acceptance).Trim() -ne "11fb1d455d79cf2918a57391455077210e924e5d") { throw "candidate moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/high-contrast-acceptance origin/work/high-contrast-acceptance
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "11fb1d455d79cf2918a57391455077210e924e5d") { throw "candidate mismatch" }
python -X utf8 -m py_compile tests\winui\test_high_contrast_contract.py tests\winui\test_high_contrast_gui.py tests\winui\test_remote_request_preflight_contract.py tests\winui\test_remote_windows_task_contract.py tools\winui\validate_remote_request.py
if ($LASTEXITCODE -ne 0) { throw "changed Python syntax failed" }
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "HIGH_CONTRAST_FINAL_INTEGRATED_SOURCE_PASS"
